import { useUser } from '../contexts/UserContext';
import Header from '../components/Header';
import AlertPopover from '../components/PopOver/AlertPopover';
import MailPopover from '../components/PopOver/MailPopover';
import { Supplier, getAllSuppliers, createSupplier, updateSupplier, deleteSupplier } from '../api/supplierApi';
import { SearchbarInputEventDetail } from '@ionic/core';

const toHermosillo = (utc: string | undefined | null): string => {
  if (!utc) return '';
  const d = new Date(utc.includes('Z') ? utc : utc + 'Z');
  // UTC-7 for Hermosillo
  return new Date(d.getTime() - 7 * 60 * 60 * 1000).toLocaleString();
};

interface SupplierFormState {
  supplierName: string;
  contactName: string;
  phone: string;
  email: string;
  address: string;
  active: boolean;
}

const SupplierPage: React.FC = () => {
  const { companyId } = useUser();
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [filteredSuppliers, setFilteredSuppliers] = useState<Supplier[]>([]);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [showToast, setShowToast] = useState(false);
  const [toastMessage, setToastMessage] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isDeleteAlertOpen, setIsDeleteAlertOpen] = useState(false);
  const [selectedSupplier, setSelectedSupplier] = useState<Supplier | null>(null);
  const [formState, setFormState] = useState<SupplierFormState>({
    supplierName: '',
    contactName: '',
    phone: '',
    email: '',
    address: '',
    active: true,
  });
  const [searchText, setSearchText] = useState('');
  const [page, setPage] = useState(0);
  const itemsPerPage = 20;

  const [popoverState, setPopoverState] = useState<{
    showAlertPopover: boolean;
    showMailPopover: boolean;
    event?: Event;
  }>({ showAlertPopover: false, showMailPopover: false });

  const presentAlertPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showAlertPopover: true, event: e.nativeEvent });
  const dismissAlertPopover = () =>
    setPopoverState({ ...popoverState, showAlertPopover: false });
  const presentMailPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showMailPopover: true, event: e.nativeEvent });
  const dismissMailPopover = () =>
    setPopoverState({ ...popoverState, showMailPopover: false });

  const fetchSuppliers = async (isInitialLoad: boolean = true) => {
    if (!companyId) return;
    setLoading(true);
    setError('');
    try {
      const data = await getAllSuppliers(companyId);
      setSuppliers(data);
      setPage(1);
      setFilteredSuppliers(data.slice(0, itemsPerPage));
    } catch (err) {
      setError((err as Error).message ?? 'Error al cargar proveedores');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchSuppliers();
  }, [companyId]);

  const loadMoreItems = () => {
    const newPage = page + 1;
    const newItems = suppliers.slice(0, newPage * itemsPerPage);
    setFilteredSuppliers(newItems);
    setPage(newPage);
  };

  useEffect(() => {
    const lowercasedSearchText = searchText.toLowerCase();
    const filtered = suppliers.filter(supplier =>
      supplier.supplierName.toLowerCase().includes(lowercasedSearchText) ||
      (supplier.contactName && supplier.contactName.toLowerCase().includes(lowercasedSearchText)) ||
      (supplier.email && supplier.email.toLowerCase().includes(lowercasedSearchText)) ||
      (supplier.phone && supplier.phone.toLowerCase().includes(lowercasedSearchText))
    );
    setFilteredSuppliers(filtered.slice(0, itemsPerPage));
    setPage(1);
  }, [searchText, suppliers]);

  const resetForm = () => {
    setFormState({
      supplierName: '',
      contactName: '',
      phone: '',
      email: '',
      address: '',
      active: true,
    });
    setSelectedSupplier(null);
  };

  const openCreateModal = () => {
    resetForm();
    setIsModalOpen(true);
  };

  const openEditModal = (supplier: Supplier) => {
    setSelectedSupplier(supplier);
    setFormState({
      supplierName: supplier.supplierName,
      contactName: supplier.contactName || '',
      phone: supplier.phone || '',
      email: supplier.email || '',
      address: supplier.address || '',
      active: supplier.active === '1',
    });
    setIsModalOpen(true);
  };

  const handleSaveSupplier = async () => {
    if (!companyId) {
      setToastMessage('ID de compañía no disponible.');
      setShowToast(true);
      return;
    }
    if (!formState.supplierName.trim()) {
      setToastMessage('El nombre del proveedor es obligatorio.');
      setShowToast(true);
      return;
    }

    setSaving(true);
    setError('');
    try {
      const payload = {
        companyId,
        supplierName: formState.supplierName.trim(),
        contactName: formState.contactName.trim() || null,
        phone: formState.phone.trim() || null,
        email: formState.email.trim() || null,
        address: formState.address.trim() || null,
        active: formState.active ? '1' : '0',
      };

      if (selectedSupplier) {
        await updateSupplier(selectedSupplier.supplierId, payload);
        setToastMessage('Proveedor actualizado con éxito.');
      } else {
        await createSupplier(payload);
        setToastMessage('Proveedor creado con éxito.');
      }
      setShowToast(true);
      setIsModalOpen(false);
      fetchSuppliers(); // Refresh list
    } catch (err) {
      setError((err as Error).message ?? 'Error al guardar proveedor');
    } finally {
      setSaving(false);
    }
  };

  const handleDeleteConfirmation = (supplier: Supplier) => {
    setSelectedSupplier(supplier);
    setIsDeleteAlertOpen(true);
  };

  const handleDeleteSupplier = async () => {
    if (!selectedSupplier || !companyId) return;
    setLoading(true);
    setError('');
    try {
      await deleteSupplier(selectedSupplier.supplierId, companyId);
      setToastMessage('Proveedor eliminado con éxito.');
      setShowToast(true);
      fetchSuppliers(); // Refresh list
    } catch (err) {
      setError((err as Error).message ?? 'Error al eliminar proveedor');
    } finally {
      setLoading(false);
      setIsDeleteAlertOpen(false);
      setSelectedSupplier(null);
    }
  };

  return (
    <IonPage className="supplier-page">
      <Header
        presentAlertPopover={presentAlertPopover}
        presentMailPopover={presentMailPopover}
        screenTitle="Proveedores — POS GMO"
      />
      <AlertPopover
        isOpen={popoverState.showAlertPopover}
        event={popoverState.event}
        onDidDismiss={dismissAlertPopover}
      />
      <MailPopover
        isOpen={popoverState.showMailPopover}
        event={popoverState.event}
        onDidDismiss={dismissMailPopover}
      />

      <IonContent fullscreen className="ion-padding">
        <IonSearchbar
          placeholder="Buscar proveedores"
          value={searchText}
          onIonInput={(e: CustomEvent<SearchbarInputEventDetail>) => setSearchText(e.detail.value!)}
          debounce={300}
        />

        <IonList className="supplier-list">
          {filteredSuppliers.length === 0 && !loading && (
            <IonItem><IonLabel>No hay proveedores registrados.</IonLabel></IonItem>
          )}
          {filteredSuppliers.map((supplier) => (
            <IonItem key={supplier.supplierId} className="supplier-item">
              <IonLabel>
                <h2>{supplier.supplierName}</h2>
                <p>{supplier.contactName} - {supplier.phone}</p>
                <p>{supplier.email}</p>
                <p className={supplier.active === '1' ? 'active-status' : 'inactive-status'}>
                  {supplier.active === '1' ? 'Activo' : 'Inactivo'}
                </p>
                <p>Creado: {toHermosillo(supplier.created_At)}</p>
                {supplier.updated_at && <p>Actualizado: {toHermosillo(supplier.updated_at)}</p>}
              </IonLabel>
              <IonButton fill="clear" onClick={() => openEditModal(supplier)}>
