              <IonTitle>{selectedSupplier ? 'Editar Proveedor' : 'Crear Proveedor'}</IonTitle>
              <IonButton slot="end" fill="clear" onClick={() => setIsModalOpen(false)}>
                <IonIcon icon={closeOutline} />
              </IonButton>
            </IonToolbar>
          </IonHeader>
          <IonContent className="ion-padding">
            <form onSubmit={(e) => {
              e.preventDefault();
              handleSaveSupplier();
            }}>
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
